# Biotic Response page: predictions with uncertainty for the current scenario ---

VB_THEMES <- c(N1 = "primary", N2 = "teal", Margalef = "indigo")

metric_value_box <- function(ns, m) {
  row <- METRICS[METRICS$id == m, ]
  value_box(
    title = row$label,
    value = textOutput(ns(paste0("v_", m)), inline = TRUE),
    showcase = icon(row$icon),
    theme = VB_THEMES[[m]],
    uiOutput(ns(paste0("d_", m))),
    tags$p(class = "small opacity-75 mb-0", row$short)
  )
}

mod_biotic_ui <- function(id) {
  ns <- NS(id)
  tagList(
    div(class = "d-flex flex-wrap align-items-center justify-content-between gap-2 mb-2",
        h4(class = "mb-0", textOutput(ns("heading"), inline = TRUE)),
        checkboxGroupInput(ns("metrics"), NULL, inline = TRUE,
                           choices = stats::setNames(METRICS$id, METRICS$label),
                           selected = METRICS$id)),
    uiOutput(ns("envelope")),
    div(class = "vb-grid mb-3",
        lapply(METRICS$id, function(m) {
          conditionalPanel(sprintf("input.metrics && input.metrics.indexOf('%s') > -1", m),
                           ns = ns, metric_value_box(ns, m))
        })),
    layout_columns(
      col_widths = breakpoints(sm = 12, lg = c(5, 7)),
      card(
        full_screen = TRUE,
        card_header(icon("chart-simple"), " This scenario against sampled sites"),
        plotlyOutput(ns("position"), height = "380px"),
        card_footer(class = "small text-muted",
                    "Grey points are observed values at sampled sites (box = middle 50%).",
                    "The orange diamond is the prediction for the current scenario with its",
                    "95% confidence interval.")
      ),
      card(
        full_screen = TRUE,
        card_header(
          class = "d-flex flex-wrap justify-content-between align-items-center gap-2",
          tags$span(icon("table-list"), " Scenario log"),
          div(class = "d-flex gap-1",
              actionButton(ns("save"), "Save scenario", icon = icon("plus"),
                           class = "btn-primary btn-sm"),
              downloadButton(ns("download"), "CSV", class = "btn-outline-secondary btn-sm"),
              actionButton(ns("clear"), NULL, icon = icon("trash-can"),
                           class = "btn-outline-secondary btn-sm", title = "Clear log"))
        ),
        DT::DTOutput(ns("log")),
        card_footer(class = "small text-muted",
                    "Save scenarios to compare what-if conditions side by side, then",
                    "download them as CSV.")
      )
    )
  )
}

mod_biotic_server <- function(id, app, scenario) {
  moduleServer(id, function(input, output, session) {
    preds <- reactive({
      s <- scenario()
      predict_metrics(s$models, s$newdata, s$data)
    })

    output$heading <- renderText(paste("Predicted diversity:", TAXA[[scenario()$taxa]]))

    lapply(METRICS$id, function(m) {
      output[[paste0("v_", m)]] <- renderText({
        p <- preds()
        fmt(p$fit[p$metric == m])
      })
      output[[paste0("d_", m)]] <- renderUI({
        p <- preds()[preds()$metric == m, ]
        floor <- METRICS$floor[METRICS$id == m]
        tagList(
          if (p$fit < floor) {
            tags$p(class = "mb-1 fw-semibold",
                   icon("triangle-exclamation"),
                   sprintf(" Below the index's minimum possible value (%g): the model is extrapolating.",
                           floor))
          },
          tags$p(class = "mb-1", sprintf("95%% CI %s – %s", fmt(p$lwr), fmt(p$upr))),
          tags$p(class = "mb-1",
                 sprintf("At or above %.0f%% of sampled sites (median %s)",
                         p$percentile, fmt(p$obs_median)))
        )
      })
    })

    output$envelope <- renderUI({
      s <- scenario()
      chk <- envelope_check(s$newdata, s$data, s$taxa)
      if (chk$inside) {
        div(class = "envelope-ok small mb-2",
            icon("circle-check"),
            " These conditions resemble sampled sites, so the models are interpolating.")
      } else {
        div(class = "alert alert-warning d-flex gap-2 align-items-start py-2 mb-3", role = "alert",
            icon("triangle-exclamation", class = "mt-1"),
            div(tags$strong("Extrapolation. "),
                "No sampled site has a combination of conditions like this one",
                sprintf("(distance to the nearest sample %.1f vs. a typical %.1f).",
                        chk$distance, chk$nearest_typical),
                "Each slider is within its observed range, but together they fall outside",
                "the data, so treat these predictions with caution."))
      }
    })

    output$position <- renderPlotly({
      s <- scenario()
      sel <- intersect(METRICS$id, input$metrics)
      validate(need(length(sel) > 0, "Select at least one metric above."))
      p <- preds()
      plots <- lapply(seq_along(sel), function(i) {
        m <- sel[i]
        pr <- p[p$metric == m, ]
        lab <- metric_label(m)
        plot_ly() |>
          add_trace(
            type = "box", y = s$data[[m]], x = rep(lab, nrow(s$data)), name = "Sampled sites",
            legendgroup = "obs", showlegend = i == 1,
            boxpoints = "all", jitter = 0.45, pointpos = 0,
            marker = list(color = PALETTE$observed, size = 5, opacity = 0.55),
            line = list(color = PALETTE$observed, width = 1.5),
            fillcolor = "rgba(138,153,168,0.12)", hoverinfo = "y"
          ) |>
          add_trace(
            type = "scatter", mode = "markers", x = lab, y = pr$fit,
            name = "Scenario (95% CI)", legendgroup = "pred", showlegend = i == 1,
            error_y = list(type = "data", symmetric = FALSE,
                           array = pr$upr - pr$fit, arrayminus = pr$fit - pr$lwr,
                           color = PALETTE$accent, thickness = 2.5, width = 10),
            marker = list(symbol = "diamond", size = 15, color = PALETTE$accent,
                          line = list(color = "white", width = 1.5)),
            hovertemplate = sprintf("Prediction %s<br>95%% CI %s – %s<extra></extra>",
                                    fmt(pr$fit), fmt(pr$lwr), fmt(pr$upr))
          ) |>
          layout(yaxis = list(title = lab, gridcolor = PALETTE$grid, zeroline = FALSE),
                 xaxis = list(showticklabels = FALSE))
      })
      subplot(plots, nrows = 1, margin = 0.08, titleY = TRUE) |>
        style_plot(legend = TRUE, axes = FALSE) |>
        layout(legend = list(orientation = "h", x = 0.5, xanchor = "center", y = 1.1),
               margin = list(l = 70, r = 10, t = 40, b = 10))
    })

    # Scenario log -----------------------------------------------------------
    log <- reactiveVal(NULL)

    observeEvent(input$save, {
      s <- scenario()
      p <- preds()
      row <- data.frame(Saved = format(Sys.time(), "%Y-%m-%d %H:%M:%S"),
                        Assemblage = TAXA[[s$taxa]], check.names = FALSE)
      for (v in c(PREDICTORS$var, "StreamOrder")) {
        row[[v]] <- if (v %in% names(s$newdata)) as.character(s$newdata[[v]][1]) else NA
      }
      for (m in METRICS$id) {
        pm <- p[p$metric == m, ]
        row[[m]] <- pm$fit
        row[[paste0(m, "_lwr")]] <- pm$lwr
        row[[paste0(m, "_upr")]] <- pm$upr
      }
      row$Extrapolation <- !envelope_check(s$newdata, s$data, s$taxa)$inside
      log(rbind(log(), row))
      showNotification("Scenario saved to the log.", type = "message", duration = 2)
    })

    observeEvent(input$clear, log(NULL))

    output$log <- DT::renderDT({
      x <- log()
      if (is.null(x)) {
        x <- data.frame(Message = "No saved scenarios yet. Click “Save scenario”.")
        return(DT::datatable(x, rownames = FALSE, options = list(dom = "t", ordering = FALSE)))
      }
      show <- data.frame(
        `#` = seq_len(nrow(x)),
        Assemblage = x$Assemblage,
        `Hill's N1` = sprintf("%s (%s–%s)", fmt(x$N1), fmt(x$N1_lwr), fmt(x$N1_upr)),
        `Hill's N2` = sprintf("%s (%s–%s)", fmt(x$N2), fmt(x$N2_lwr), fmt(x$N2_upr)),
        Margalef = sprintf("%s (%s–%s)", fmt(x$Margalef), fmt(x$Margalef_lwr), fmt(x$Margalef_upr)),
        pH = fmt(as.numeric(x$pH)),
        `Temp (°C)` = fmt(as.numeric(x$WaterTemp), 1),
        `Extrapolated?` = ifelse(x$Extrapolation, "yes", "no"),
        check.names = FALSE
      )
      DT::datatable(show, rownames = FALSE, selection = "none", class = "compact stripe nowrap",
                    options = list(dom = "tp", pageLength = 6, scrollX = TRUE, ordering = FALSE))
    })

    output$download <- downloadHandler(
      filename = function() sprintf("signal2noise-scenarios-%s.csv", format(Sys.Date())),
      content = function(file) {
        x <- log()
        if (is.null(x)) x <- data.frame(Message = "No saved scenarios")
        utils::write.csv(x, file, row.names = FALSE)
      }
    )
  })
}

# Data page: browse and download the modeling data --------------------------------

mod_data_ui <- function(id, app) {
  ns <- NS(id)
  tagList(
    card(
      full_screen = TRUE,
      card_header(
        class = "d-flex flex-wrap justify-content-between align-items-center gap-2",
        tags$span(icon("table"), " ", textOutput(ns("title"), inline = TRUE)),
        downloadButton(ns("download"), "Download CSV", class = "btn-outline-primary btn-sm")
      ),
      DT::DTOutput(ns("table"))
    ),
    card(card_header(icon("circle-info"), " Data notes"), help_data_notes(app))
  )
}

mod_data_server <- function(id, app, scenario) {
  moduleServer(id, function(input, output, session) {
    tbl <- reactive({
      d <- app$data[[scenario()$taxa]]
      d$Date <- format(d$DateTime, "%Y-%m-%d", tz = "UTC")
      d$DateTime <- NULL
      d[c("StationID", "StationName", "Date", setdiff(names(d), c("StationID", "StationName", "Date")))]
    })

    output$title <- renderText(sprintf("Modeling data: %s (%d samples)",
                                       TAXA[[scenario()$taxa]], nrow(tbl())))

    output$table <- DT::renderDT({
      d <- tbl()
      names(d)[names(d) == "N1"] <- "Hill's N1"
      names(d)[names(d) == "N2"] <- "Hill's N2"
      num <- names(d)[vapply(d, is.numeric, logical(1)) & names(d) != "StationID"]
      DT::datatable(d, rownames = FALSE, filter = "top", selection = "none",
                    options = list(pageLength = 10, scrollX = TRUE, autoWidth = FALSE,
                                   dom = "tip")) |>
        DT::formatRound(num, digits = 3)
    })

    output$download <- downloadHandler(
      filename = function() sprintf("signal2noise-%s-data.csv", scenario()$taxa),
      content = function(file) utils::write.csv(tbl(), file, row.names = FALSE)
    )
  })
}

# GAM specification, fitting and caching ----------------------------------------
# Six generalized additive models (mgcv): {macroinvertebrates, fish} x
# {Hill's N1, Hill's N2, Margalef}. Specifications are unchanged from 2019.

CACHE_SCHEMA <- 3L

# Fish basis dimensions came from a grid search over k = 3..8 for each of the
# seven smooths (data/Gam_Grid_outlier_removal.csv, column V1 = GCV score).
best_fish_k <- function(path = PATHS$grid) {
  grid <- utils::read.csv(path, row.names = 1)
  best <- unlist(grid[which.min(grid$V1), paste0("x", 1:7)])
  stats::setNames(as.integer(best), TAXA_PREDICTORS$fish)
}

model_formula <- function(taxa, response, fish_k = NULL) {
  rhs <- if (taxa == "macro") {
    c("s(pH, k = 10)",
      "s(WaterTemp, k = 10)",
      "s(Turbidity, k = 10, bs = 'ad')",
      "s(SpCond, k = 15, bs = 'ad')",
      "s(O2Dis, k = 10, bs = 'ad')",
      "s(Oxygen, k = 10, bs = 'ad')",
      "s(Flow, k = 15)",
      "s(Alkalinity, k = 15, bs = 'ad')",
      "StreamOrder")
  } else {
    sprintf("s(%s, k = %d)", names(fish_k), fish_k)
  }
  # Global env keeps the cached model objects small (no captured frames).
  stats::as.formula(paste(response, "~", paste(rhs, collapse = " + ")),
                    env = globalenv())
}

fit_models <- function(data, fish_k) {
  sapply(names(TAXA), function(taxa) {
    sapply(METRICS$id, function(metric) {
      mgcv::gam(model_formula(taxa, metric, fish_k),
                data = data[[taxa]], na.action = stats::na.omit)
    }, simplify = FALSE)
  }, simplify = FALSE)
}

build_app_data <- function() {
  raw <- load_raw_data()
  data <- list(
    macro = prepare_macro(raw$allData3, raw$allDatat),
    fish  = prepare_fish(raw$allData2)
  )
  fish_k <- best_fish_k()
  list(
    data     = data,
    stations = station_table(raw$allDatat),
    fish_k   = fish_k,
    models   = fit_models(data, fish_k),
    built    = Sys.time()
  )
}

cache_fingerprint <- function() {
  list(
    schema = CACHE_SCHEMA,
    mgcv   = as.character(utils::packageVersion("mgcv")),
    inputs = unname(tools::md5sum(c(PATHS$data, PATHS$grid)))
  )
}

# Fitting takes ~10-30 s, so fitted models are cached in data/model_cache.rds
# and refit only when the data, grid file or mgcv version changes.
# Without the raw inputs (the in-browser Shinylive build ships only the cache)
# the cached models are used as they are.
load_app_data <- function(rebuild = FALSE, cache = PATHS$cache) {
  # Register mgcv's S3 methods (summary.gam, predict.gam, ...) before any cached
  # model is used; otherwise summary() silently dispatches to summary.glm.
  loadNamespace("mgcv")
  have_inputs <- all(file.exists(c(PATHS$data, PATHS$grid)))
  if (!rebuild && file.exists(cache)) {
    obj <- tryCatch(readRDS(cache), error = function(e) NULL)
    if (!is.null(obj) && (!have_inputs || identical(obj$fingerprint, cache_fingerprint()))) {
      return(obj)
    }
    message("Model cache is stale or unreadable; refitting models.")
  }
  if (!have_inputs) {
    stop("Cannot fit models: ", PATHS$data, " or ", PATHS$grid, " is missing.", call. = FALSE)
  }
  obj <- build_app_data()
  obj$fingerprint <- cache_fingerprint()
  tryCatch(saveRDS(obj, cache),
           error = function(e) message("Could not write model cache: ", conditionMessage(e)))
  obj
}

model_summary_row <- function(model, taxa, metric) {
  s <- summary(model)
  data.frame(
    Assemblage   = TAXA[[taxa]],
    Metric       = metric_label(metric),
    n            = s$n,
    `Deviance explained` = s$dev.expl,
    `Adj. R²` = s$r.sq,
    GCV          = model$gcv.ubre,
    check.names  = FALSE
  )
}

smooth_table <- function(model) {
  st <- as.data.frame(summary(model)$s.table)
  data.frame(
    Term      = sub("^s\\((.*)\\)$", "\\1", rownames(st)),
    edf       = st$edf,
    `Ref. df` = st$Ref.df,
    F         = st$F,
    `p-value` = st$`p-value`,
    check.names = FALSE
  )
}

# Prediction, uncertainty and sensitivity helpers -------------------------------

# Slider defaults reproduce the 2019 app: median pH, mean of everything else,
# and stream order = integer part of the mean order.
default_scenario <- function(data, taxa) {
  vars <- TAXA_PREDICTORS[[taxa]]
  vals <- lapply(vars, function(v) if (v == "pH") stats::median(data[[v]]) else mean(data[[v]]))
  names(vals) <- vars
  if (taxa == "macro") {
    vals$StreamOrder <- as.character(as.integer(mean(as.integer(data$StreamOrder))))
  }
  vals
}

# Turn a named list of predictor values into a one-row newdata frame.
scenario_frame <- function(values, taxa, data) {
  vars <- TAXA_PREDICTORS[[taxa]]
  nd <- as.data.frame(lapply(values[vars], as.numeric))
  if (taxa == "macro") {
    nd$StreamOrder <- factor(as.character(values$StreamOrder),
                             levels = levels(data$StreamOrder))
  }
  nd
}

predict_ci <- function(model, newdata, level = 0.95) {
  p <- mgcv::predict.gam(model, newdata, type = "response", se.fit = TRUE)
  z <- stats::qnorm(1 - (1 - level) / 2)
  fit <- as.numeric(p$fit)
  se <- as.numeric(p$se.fit)
  data.frame(fit = fit, se = se, lwr = fit - z * se, upr = fit + z * se)
}

predict_metrics <- function(models, newdata, data) {
  rows <- lapply(METRICS$id, function(m) {
    p <- predict_ci(models[[m]], newdata)
    obs <- data[[m]]
    cbind(metric = m, label = metric_label(m), p,
          percentile = 100 * mean(obs <= p$fit),
          obs_median = stats::median(obs))
  })
  do.call(rbind, rows)
}

# Is the scenario inside the cloud of sampled conditions? Compare the distance
# from the scenario to its nearest sample (standardized predictor space) with
# the nearest-neighbour distances among the samples themselves.
envelope_check <- function(newdata, data, taxa, quantile = 0.95) {
  vars <- TAXA_PREDICTORS[[taxa]]
  X <- as.matrix(data[vars])
  mu <- colMeans(X)
  sdv <- apply(X, 2, stats::sd)
  Z <- sweep(sweep(X, 2, mu), 2, sdv, "/")
  z <- (as.numeric(newdata[1, vars]) - mu) / sdv
  d_new <- min(sqrt(colSums((t(Z) - z)^2)))
  D <- as.matrix(stats::dist(Z))
  diag(D) <- Inf
  nn <- apply(D, 1, min)
  threshold <- stats::quantile(nn, quantile, names = FALSE)
  list(distance = d_new, threshold = threshold, inside = d_new <= threshold,
       nearest_typical = stats::median(nn))
}

# One-at-a-time response curve for a single driver.
response_curve <- function(model, base, data, var, n = 120) {
  if (var == "StreamOrder") {
    lv <- levels(data$StreamOrder)
    lv <- lv[lv %in% unique(as.character(data$StreamOrder))]
    nd <- base[rep(1, length(lv)), , drop = FALSE]
    nd$StreamOrder <- factor(lv, levels = levels(data$StreamOrder))
    return(cbind(x = lv, predict_ci(model, nd)))
  }
  rng <- range(data[[var]])
  nd <- base[rep(1, n), , drop = FALSE]
  nd[[var]] <- seq(rng[1], rng[2], length.out = n)
  cbind(x = nd[[var]], predict_ci(model, nd))
}

# Tornado sensitivity: move each driver from its 10th to 90th percentile while
# holding the others at the scenario values. Stream order uses the spread
# across observed orders.
tornado_data <- function(model, base, data, taxa, probs = c(0.1, 0.9)) {
  vars <- TAXA_PREDICTORS[[taxa]]
  base_fit <- predict_ci(model, base)$fit
  rows <- lapply(vars, function(v) {
    q <- stats::quantile(data[[v]], probs, names = FALSE)
    nd <- base[c(1, 1), , drop = FALSE]
    nd[[v]] <- q
    f <- predict_ci(model, nd)$fit
    data.frame(var = v, low_x = q[1], high_x = q[2], at_low = f[1], at_high = f[2])
  })
  if (taxa == "macro") {
    rc <- response_curve(model, base, data, "StreamOrder")
    rows[[length(rows) + 1]] <- data.frame(
      var = "StreamOrder",
      low_x = rc$x[which.min(rc$fit)], high_x = rc$x[which.max(rc$fit)],
      at_low = min(rc$fit), at_high = max(rc$fit))
  }
  out <- do.call(rbind, rows)
  out$label <- predictor_label(out$var)
  out$swing <- abs(out$at_high - out$at_low)
  out$base <- base_fit
  out[order(out$swing), ]
}

station_summary <- function(data, stations) {
  agg <- stats::aggregate(cbind(N1, N2, Margalef) ~ StationID, data = data, FUN = mean)
  agg$samples <- as.vector(table(data$StationID)[as.character(agg$StationID)])
  out <- merge(agg, stations, by = "StationID", all.x = TRUE)
  out$StreamOrder <- as.character(out$StreamOrder)
  out
}

# Mean conditions at a station, clamped to the slider ranges.
station_scenario <- function(data, station_id, taxa) {
  rows <- data[data$StationID == station_id, , drop = FALSE]
  if (!nrow(rows)) return(NULL)
  vals <- lapply(TAXA_PREDICTORS[[taxa]], function(v) mean(rows[[v]]))
  names(vals) <- TAXA_PREDICTORS[[taxa]]
  if (taxa == "macro") vals$StreamOrder <- as.character(rows$StreamOrder[1])
  vals
}

# Theme, sidebar and plot helpers ------------------------------------------------

app_theme <- function() {
  fonts <- bslib::font_collection("Segoe UI", "system-ui", "-apple-system", "Roboto",
                                  "Helvetica Neue", "Arial", "sans-serif")
  bslib::bs_theme(
    version = 5,
    primary = PALETTE$primary,
    secondary = "#5B6B7B",
    success = "#2E7D5B",
    warning = PALETTE$accent,
    info = "#3D85C6",
    base_font = fonts,
    heading_font = fonts,
    "border-radius" = "0.6rem"
  )
}

slider_step <- function(x) 10^floor(log10(diff(range(x)) / 100))

predictor_slider <- function(var, taxa, data, default) {
  x <- data[[var]]
  step <- slider_step(x)
  lo <- floor(min(x) / step) * step
  hi <- ceiling(max(x) / step) * step
  coded <- PREDICTORS$coded[PREDICTORS$var == var]
  label <- if (coded) {
    tags$span(predictor_label(var), " ",
              bslib::tooltip(shiny::icon("circle-exclamation", class = "text-warning"),
                             CODED_NOTE))
  } else predictor_label(var)
  shiny::sliderInput(input_id(var, taxa), label, min = lo, max = hi,
                     value = default, step = step, ticks = FALSE, width = "100%")
}

slider_accordion <- function(taxa, data) {
  defaults <- default_scenario(data, taxa)
  vars <- TAXA_PREDICTORS[[taxa]]
  groups <- PREDICTORS$group[match(vars, PREDICTORS$var)]
  panels <- lapply(unique(groups), function(g) {
    bslib::accordion_panel(
      g, icon = shiny::icon(if (g == "Field sonde") "water" else "flask"),
      lapply(vars[groups == g], function(v) predictor_slider(v, taxa, data, defaults[[v]]))
    )
  })
  if (taxa == "macro") {
    lv <- levels(data$StreamOrder)
    n <- table(factor(data$StreamOrder, levels = lv))
    panels[[length(panels) + 1]] <- bslib::accordion_panel(
      "Site", icon = shiny::icon("route"),
      shiny::radioButtons(input_id("StreamOrder", taxa), "Stream order",
                          choices = lv, selected = defaults$StreamOrder, inline = TRUE),
      tags$p(class = "small text-muted mb-0",
             sprintf("Samples per order: %s.", paste(sprintf("%s = %d", lv, n), collapse = ", ")),
             "Orders with few samples have wide intervals.")
    )
  }
  do.call(bslib::accordion,
          c(panels, list(open = TRUE, multiple = TRUE, class = "accordion-flush")))
}

scenario_sidebar <- function(app) {
  bslib::sidebar(
    id = "sidebar", title = "Scenario", width = 330, open = "desktop",
    shiny::radioButtons(
      "taxa", "Assemblage",
      choiceNames = list(tagList(shiny::icon("bug"), " Macroinvertebrates"),
                         tagList(shiny::icon("fish"), " Fish")),
      choiceValues = names(TAXA), inline = TRUE
    ),
    shiny::conditionalPanel("input.taxa == 'macro'", slider_accordion("macro", app$data$macro)),
    shiny::conditionalPanel("input.taxa == 'fish'", slider_accordion("fish", app$data$fish)),
    shiny::actionButton("reset", "Reset to typical conditions", icon = shiny::icon("rotate-left"),
                        class = "btn-outline-primary btn-sm w-100"),
    tags$p(class = "small text-muted mb-0",
           "Slider ranges span the sampled conditions. Defaults are the sample",
           "median (pH) or mean (all others), as in the original app.")
  )
}

apply_scenario <- function(session, taxa, values) {
  for (v in names(values)) {
    id <- input_id(v, taxa)
    if (v == "StreamOrder") {
      shiny::updateRadioButtons(session, id, selected = values[[v]])
    } else {
      shiny::updateSliderInput(session, id, value = values[[v]])
    }
  }
}

read_news <- function(path = PATHS$news) {
  if (!file.exists(path)) return(data.frame(from = character(), message = character()))
  x <- suppressWarnings(utils::read.csv(path, check.names = FALSE, strip.white = TRUE,
                                        stringsAsFactors = FALSE))
  names(x) <- trimws(names(x))
  x
}

news_popover <- function(news) {
  items <- if (nrow(news)) {
    tags$ul(class = "list-unstyled mb-0",
            lapply(seq_len(nrow(news)), function(i) {
              tags$li(class = "mb-2", tags$strong(news$from[i]), tags$br(),
                      tags$span(class = "small", news$message[i]))
            }))
  } else tags$p("No updates.")
  bslib::popover(
    tags$a(href = "#", class = "nav-link position-relative", `aria-label` = "Project updates",
           shiny::icon("bell"),
           if (nrow(news)) tags$span(class = "badge rounded-pill bg-warning text-dark news-badge",
                                     nrow(news))),
    items, title = "Project updates", placement = "bottom"
  )
}

# Plotly styling shared by every chart.
# `axes = FALSE` leaves axis settings alone (for subplots, whose panels style
# their own axes; overriding `xaxis` here would only hit the first panel).
style_plot <- function(p, xlab = NULL, ylab = NULL, legend = FALSE, axes = TRUE) {
  axis <- function(title) {
    a <- list(gridcolor = PALETTE$grid, zeroline = FALSE,
              linecolor = "#C9D3DD", ticks = "outside", tickcolor = "#C9D3DD")
    if (!is.null(title)) a$title <- list(text = title, standoff = 8)
    a
  }
  if (axes) p <- plotly::layout(p, xaxis = axis(xlab), yaxis = axis(ylab))
  p |>
    plotly::layout(
      font = list(family = "Segoe UI, system-ui, sans-serif", size = 12, color = PALETTE$ink),
      showlegend = legend,
      legend = list(orientation = "h", y = -0.2),
      margin = list(l = 60, r = 20, t = 30, b = 50),
      hoverlabel = list(bgcolor = "white", bordercolor = "#C9D3DD",
                        font = list(color = PALETTE$ink)),
      paper_bgcolor = "rgba(0,0,0,0)", plot_bgcolor = "rgba(0,0,0,0)"
    ) |>
    plotly::config(displaylogo = FALSE,
                   modeBarButtonsToRemove = c("lasso2d", "select2d", "autoScale2d",
                                              "toggleSpikelines", "hoverCompareCartesian"))
}

